def transform(grid):
    n = len(grid) // 3
    m = len(grid[0]) // 3
    out = [[0 for _ in range(m)] for _ in range(n)]
    for r in range(n):
        for c in range(m):
            colors = [grid[i][j] for i in range(3*r, 3*r+3) for j in range(3*c, 3*c+3) if grid[i][j] not in (0, 5)]
            if colors:
                out[r][c] = colors[0]
    return out

